INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31227$nota-0198$m31227$, $m31228$Manual treinamento.pdf$m31228$, $m31229$162$m31229$, $m31230$Um dos maiores erros do treinamento moderno consiste em analisar cada variável isoladamente... Um atleta apresenta: potência reduzida; frequência cardíaca elevada; percepção subjetiva alta; sono ruim; VFC reduzida. Interpretadas em conjunto, essas informações sugerem fadiga acumulada. Entretanto, se apenas a potência fosse analisada, outras interpretações poderiam ser feitas.$m31230$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31231$nota-0198$m31231$, $m31232$nota-0185$m31232$, $m31233$pre-requisito$m31233$, $m31234$aplica, em forma de regra prática, a distinção entre carga externa (potência) e carga interna (FC/RPE) já estabelecida na nota-0185$m31234$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31235$nota-0198$m31235$, $m31236$nota-0194$m31236$, $m31237$complementa$m31237$, $m31238$reforça, na direção oposta, a cautela da nota-0194 de que TSS/potência isolados não medem fadiga real$m31238$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31239$nota-0198$m31239$, $m31240$nota-0158$m31240$, $m31241$complementa$m31241$, $m31242$fatores de confusão da FC (nota-0158), citados no corpo da nota como redutores de falsos positivos ao exigir concordância de sinais — link estrutural ausente até auditoria de 2026-08-02$m31242$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31243$nota-0198$m31243$, $m31244$nota-0191$m31244$, $m31245$complementa$m31245$, $m31246$carga externa vs. interna (nota-0191), citada junto com nota-0158 no corpo da nota — link estrutural ausente até auditoria de 2026-08-02$m31246$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31247$nota-0232$m31247$, $m31248$Exercise Physiology McArdle.pdf$m31248$, $m31249$169$m31249$, $m31250$The excess oxygen consumption has classically been termed oxygen debt or recovery oxygen consumption, with the newer preferred term the excess postexercise oxygen consumption or EPOC... EPOC computes as the total oxygen consumed in recovery minus the total oxygen theoretically consumed at rest during the recovery period.$m31250$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31251$nota-0232$m31251$, $m31252$Exercise Physiology McArdle.pdf$m31252$, $m31253$170$m31253$, $m31254$With mild aerobic activity of relatively short duration... about half of the total recovery oxygen consumption occurs within 30 s, and complete recovery within 2 to 4 min... Depending on the intensity and duration of the previous physical activity, the slow component can take up to 24 hr to return to pre-exercise oxygen consumption. Even with shorter, intermittent bouts of 'supermaximal' effort (e.g., three 2-min bouts at 108% VO2max interspersed with 3-min rest intervals), recovery oxygen consumption remains elevated for 1 hr or longer.$m31254$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31255$nota-0232$m31255$, $m31256$nota-0229$m31256$, $m31257$complementa$m31257$, $m31258$espelha, na recuperação, o mesmo fenômeno de cinética não-instantânea de VO2 descrito no início do exercício (déficit de oxigênio, nota-0229)$m31258$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31259$nota-0232$m31259$, $m31260$nota-0148$m31260$, $m31261$complementa$m31261$, $m31262$fornece um mecanismo fisiológico (EPOC de componente lento, até 24h) que ajuda a explicar por que esforços intensos/supermáximos produzem fadiga residual muito além do fim da sessão, relevante ao contraste overreached vs. overtrained já na nota-0148$m31262$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31263$nota-0233$m31263$, $m31264$Exercise Physiology McArdle.pdf$m31264$, $m31265$173$m31265$, $m31266$Figure 7.11 illustrates blood lactate recovery patterns for trained men who performed 6 min of supermaximal exercise on a bicycle ergometer. Active recovery involved 40 min of continuous cycling at either 35 or 65% VO2max... The results indicated that moderate aerobic activity (35% VO2max) performed in recovery better facilitates lactate removal compared with a passive recovery procedure... Performing recovery physical activity above the lactate threshold (65% VO2max) offers no advantage and may even prolong recovery by initiating lactate formation and accumulation. The inset graph illustrates that optimal recovery intensity probably ranges between 30 and 40% VO2max.$m31266$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31267$nota-0233$m31267$, $m31268$nota-0166$m31268$, $m31269$complementa$m31269$, $m31270$aplica o conceito de remoção de lactato (lactate shuttle, nota-0166/0167) a uma recomendação prática de intensidade de recuperação ativa pós-esforço supermáximo$m31270$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31271$nota-0233$m31271$, $m31272$nota-0167$m31272$, $m31273$complementa$m31273$, $m31274$o mecanismo descrito no corpo da nota (perfusão de órgãos consumidores de lactato + oxidação via ciclo do ácido cítrico) é precisamente o Lactate Shuttle de nota-0167 (transporte MCT1/MCT4), tematicamente mais preciso que nota-0166 (que trata de terminologia lactato≠ácido lático) — achado de auditoria adversarial 2026-08-02, link a nota-0167 adicionado por precisão, nota-0166 mantida por já estar formalmente registrada$m31274$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31275$nota-0242$m31275$, $m31276$Exercise Physiology McArdle.pdf$m31276$, $m31277$449$m31277$, $m31278$Figure 20.27 describes the general J-shaped curve relating exercise volume and/or intensity and risk to URTI... a marathon run or intense training session provides an 'open window' (3 to 72 hr) that decreases antiviral and antibacterial resistance and increases risk of URTI that manifests itself within 1 to 2 wk... Approximately 13% of the participants in a Los Angeles marathon reported an episode of infectious URTI during the week following the race. For runners of comparable ability who did not compete for reasons other than illness, the infection rate approximated just 2%.$m31278$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31279$nota-0242$m31279$, $m31280$Exercise Physiology McArdle.pdf$m31280$, $m31281$449$m31281$, $m31282$light to moderate physical activity offers more protection against URTI and possibly diverse cancers than a sedentary lifestyle... Moderate physical activity does not exacerbate the severity and duration of illness when an infection occurs.$m31282$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31283$nota-0242$m31283$, $m31284$nota-0092$m31284$, $m31285$complementa$m31285$, $m31286$nota-0092 trata overreaching não-funcional via TSB negativo sustentado; esta nota cobre um mecanismo diferente e mais agudo (imunossupressão transitória pós-esforço único muito longo/intenso), relevante mesmo sem TSB cronicamente negativo$m31286$)
